// App.tsx content:
import React, { useState, useCallback } from 'react';
import { getGroundedAnswer } from './services/geminiService';
import type { GroundingChunk } from './types';
import { SearchInput } from './components/SearchInput';
import { ResultDisplay } from './components/ResultDisplay';
import { LoadingSpinner } from './components/LoadingSpinner';
import { GoogleIcon } from './components/GoogleIcon';

const App: React.FC = () => {
    const [prompt, setPrompt] = useState<string>('');
    const [resultText, setResultText] = useState<string>('');
    const [sources, setSources] = useState<GroundingChunk[]>([]);
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [error, setError] = useState<string>('');

    const handleSearch = useCallback(async () => {
        if (!prompt.trim() || isLoading) return;

        setIsLoading(true);
        setError('');
        setResultText('');
        setSources([]);

        try {
            const response = await getGroundedAnswer(prompt);
            const text = response.text;
            const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

            setResultText(text);
            setSources(groundingChunks.filter(chunk => chunk.web?.uri && chunk.web?.title));
        } catch (err) {
            console.error('API Error:', err);
            setError(err instanceof Error ? err.message : 'An unexpected error occurred. Please try again.');
        } finally {
            setIsLoading(false);
        }
    }, [prompt, isLoading]);

    return (
        <div className="min-h-screen bg-gray-900 text-gray-100 font-sans flex flex-col items-center p-4 sm:p-6">
            <main className="w-full max-w-3xl mx-auto flex flex-col flex-grow">
                <header className="text-center my-8">
                    <div className="flex items-center justify-center gap-3 mb-2">
                        <svg xmlns="http://www.w3.org/2000/svg" className="w-8 h-8 text-blue-400" viewBox="0 0 24 24" fill="currentColor"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm-2-8h4v-2h-4v2z" /></svg>
                        <h1 className="text-3xl font-bold">Denver Court Case Search</h1>
                    </div>
                    <p className="text-gray-400 text-sm">Find information on cases, judges, and legal terms.</p>
                </header>
                <SearchInput value={prompt} onChange={setPrompt} onSearch={handleSearch} isLoading={isLoading} />
                {error && <p className="text-red-500 mt-2">{error}</p>}
                {isLoading && <LoadingSpinner />}
                {!isLoading && resultText && <ResultDisplay text={resultText} sources={sources} />}
            </main>
        </div>
    );
};

export default App;
